import{z as l,x as o,o as r,c as d,q as t,j as A,D as e,d as E,s as B,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"噪声修正估计量","description":"","frontmatter":{"title":"噪声修正估计量","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hfs-noise-corrected.md","filePath":"quant/hfs-noise-corrected.md","lastUpdated":1791063341000}'),h={name:"quant/hfs-noise-corrected.md"};function p(m,a,c,C,u,F){const i=o("Mermaid");return r(),d("div",null,[a[2]||(a[2]=t('<h1 id="噪声修正估计量" tabindex="-1">噪声修正估计量 <a class="header-anchor" href="#噪声修正估计量" aria-label="Permalink to &quot;噪声修正估计量&quot;">​</a></h1><div class="epigraph"><p>噪声修正不是把坏数据变好，而是把 $2n\\sigma_\\varepsilon^2$ 这一项从估计量里精确地减掉；减法的代价写在收敛率、带宽与噪声假设里。</p><footer>—— 据 Zhang, Mykland and Aït-Sahalia, JASA 2005；Aït-Sahalia, Mykland and Zhang, Review of Financial Studies 2005 整理</footer></div><p><a href="/quant/hfs-realized-variance-family">上一课</a>把族谱立成两根轴，并留下噪声修正这条支路：噪声在场时如何恢复积分波动。<a href="/quant/tsrv">两尺度估计</a>、<a href="/quant/pre-averaging">预平均</a>与<a href="/quant/realized-kernel">已实现核</a>各写过单点，<a href="/quant/noise-variance-estimate">噪声方差估计</a>写过诊断输入；本课把这条支路收成一页对照：四家共用的机制是什么，调参落在哪，噪声假设被违反时谁先坏、怎么选。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>观测是 \\(Y=X+\\varepsilon\\)：有效价格 \\(X\\) 是半鞅，噪声方差 \\(\\sigma_\\varepsilon^2\\)。朴素 RV 的期望被 \\(2n\\sigma_\\varepsilon^2\\) 量级的加项带偏——平方把噪声的二次变差按采样次数加了进来。修正估计量的共同目标是把这个加项去掉，去掉的方式决定三件事：收敛率掉多少、要调几个参数、对「噪声 i.i.d. 且与价格独立」这条假设的依赖多深。缺口不是再发明第五种估计量，而是<strong>选择判据</strong>：给一个标的、一段数据，用哪家、怎么调、何时换。</p><h3 id="四个代表-一个机制" tabindex="-1">四个代表，一个机制 <a class="header-anchor" href="#四个代表-一个机制" aria-label="Permalink to &quot;四个代表，一个机制&quot;">​</a></h3><p><strong>两尺度（TSRV）</strong>：全网格 RV 识别 \\(2n\\sigma_\\varepsilon^2\\)，多个错开的稀疏网格平均出受污染较小的 RV，联立两式解出 \\(IV\\)（Zhang、Mykland 与 Aït-Sahalia，JASA 2005），收敛率 \\(n^{1/4}\\)，稀疏子格条数是主要调参。<strong>多尺度（MSRV）</strong>：把两尺度推广成多尺度加权组合，速率推到任意接近 \\(n^{1/2}\\)（Zhang，Bernoulli 2006），代价是多一组权重。<strong>已实现核</strong>：把噪声诱发的负一阶自协方差加权加回（Barndorff-Nielsen、Hansen、Lunde 与 Shephard，Econometrica 2008），带宽是主要调参。<strong>预平均</strong>：先用局部线性窗滤掉噪声再平方加总（Jacod、Li、Mykland、Podolskij 与 Vetter，2009），窗口长度是主要调参。<strong>拟极大似然</strong>（Aït-Sahalia、Mykland 与 Zhang，RFS 2005 及其相关噪声扩展）把噪声写进似然：模型对则效率高，模型错则偏差有结构。</p><p><span class="marginnote">数字实例：一天 \\(n=20000\\) 个 tick、\\(\\sigma_\\varepsilon^2=0.05\\) 时，朴素 RV 要多出 \\(2\\times20000\\times0.05=2000\\)，而真实日 \\(IV\\) 可能只有 1 上下；稀疏平均把有效观测降到几百，加项立刻掉一个数量级——「减法」的第一步其实是先让噪声项变小，第二步才是联立把残项解干净。</span></p><p><span class="marginnote">弹跳噪声让相邻收益出现约 \\(-\\sigma_\\varepsilon^2\\) 的负一阶自协方差——核估计量加回的正是这一项。该加多少不靠信仰，靠<a href="/quant/microstructure-noise">Roll 弹跳</a>在该标的当天的强度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选择按三问走。**第一问：噪声结构。**签名图上翘且反转明显，说明弹跳主导、噪声接近 i.i.d.，四家都能用；若噪声显示序列相关或与价格相关，优先选假设最弱的核与预平均家族，或用相关噪声下的 QMLE 扩展——两尺度在此会减过头或减不够。**第二问：调参预算。**带宽、窗口、子格数都要按数据定，且要有准则（最小化渐近方差、或跨错开格的稳定性），不许全年固定一个数。**第三问：下游要什么。**进 HAR 预报的日度 \\(IV\\) 序列要低方差与稳定，核加预平均的组合常见；盘中定位与高频对冲要日内路径与速率，多尺度或核更合身。</p>',11)),(r(),A(s,null,{default:e(()=>[B(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E7%AD%BE%E5%90%8D%E5%9B%BE%E4%B8%8E%E5%8F%8D%E8%BD%AC%E8%AF%8A%E6%96%AD%22%5D%20--%3E%20S%7B%22%E5%99%AA%E5%A3%B0%E6%8E%A5%E8%BF%91%20i.i.d.%EF%BC%9F%22%7D%0A%20%20S%20--%3E%7C%22%E6%98%AF%22%7C%20F%5B%22TSRV%E3%80%81MSRV%E3%80%81%E6%A0%B8%E3%80%81%E9%A2%84%E5%B9%B3%E5%9D%87%E3%80%81QMLE%20%E7%9A%86%E5%8F%AF%22%5D%0A%20%20S%20--%3E%7C%22%E5%90%A6%22%7C%20K%5B%22%E6%A0%B8%E4%B8%8E%E9%A2%84%E5%B9%B3%E5%9D%87%E4%B8%BA%E4%B8%BB%EF%BC%8C%E7%9B%B8%E5%85%B3%E5%99%AA%E5%A3%B0%20QMLE%20%E5%8F%AF%E9%80%89%22%5D%0A%20%20F%20--%3E%20T%7B%22%E8%B0%83%E5%8F%82%E9%A2%84%E7%AE%97%E4%B8%8E%E4%B8%8B%E6%B8%B8%22%7D%0A%20%20K%20--%3E%20T%0A%20%20T%20--%3E%7C%22%E6%97%A5%E5%BA%A6%20IV%20%E8%BF%9B%E9%A2%84%E6%8A%A5%22%7C%20R1%5B%22%E4%BD%8E%E6%96%B9%E5%B7%AE%E7%BB%84%E5%90%88%EF%BC%8C%E6%8A%A5%E5%91%8A%E5%B8%A6%E5%AE%BD%E4%B8%8E%E7%AA%97%E5%8F%A3%22%5D%0A%20%20T%20--%3E%7C%22%E6%97%A5%E5%86%85%E8%B7%AF%E5%BE%84%E4%B8%8E%E9%80%9F%E7%8E%87%22%7C%20R2%5B%22%E5%A4%9A%E5%B0%BA%E5%BA%A6%E6%88%96%E6%A0%B8%EF%BC%8C%E6%8A%A5%E5%91%8A%E5%87%86%E5%88%99%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[E("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,[E("为什么减法可行：噪声与有效价格独立时，它对 RV 的贡献是加性的、可识别的——全网格上以 \\(2n\\sigma_\\varepsilon^2\\) 的速度线性生长，而信号部分不随 \\(n\\) 生长。两个尺度对同一个 \\(IV\\) 给出两条方程，噪声项变成可解的未知数。核的机制等价：噪声的二阶结构全表现在短滞后自协方差里，用核函数吸收之后，加权和收敛到 \\(IV\\)。预平均把噪声方差在滤波里除以窗口，平方之后噪声项变成高阶小量。三家殊途同归："),n("strong",null,"噪声的二阶结构是它的软肋"),E("。一旦噪声序列相关，「负一阶自协方差」不再讲完整个故事，减法开始失准——这正是先诊断后选择的机制理由，也是假设最弱者最耐用的原因。")],-1)),(r(),A(s,null,{default:e(()=>[B(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALL%5B%22%E5%85%A8%E7%BD%91%E6%A0%BC%20RV%20%3D%20%E4%BF%A1%E5%8F%B7%20%2B%202n%CF%83%CE%B5%C2%B2%22%5D%20--%3E%20EQ%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%20IV%2C%20%E4%B8%A4%E6%9D%A1%E6%96%B9%E7%A8%8B%22%5D%0A%20%20AVG%5B%22M%20%E4%B8%AA%E9%94%99%E5%BC%80%E7%A8%80%E7%96%8F%E6%A0%BC%E5%B9%B3%E5%9D%87%20%3D%20%E4%BF%A1%E5%8F%B7%20%2B%202n%CC%84%CF%83%CE%B5%C2%B2%2C%20n%CC%84%20%E8%BF%9C%E5%B0%8F%E4%BA%8E%20n%22%5D%20--%3E%20EQ%0A%20%20EQ%20--%3E%20SOL%5B%22%E8%81%94%E7%AB%8B%E8%A7%A3%E5%87%BA%20IV%20%E4%B8%8E%E5%99%AA%E5%A3%B0%E9%A1%B9%22%5D%0A%20%20SOL%20--%3E%20RATE%5B%22%E6%94%B6%E6%95%9B%E7%8E%87%20n%5E(1%2F4)%3A%20%E5%87%8F%E6%B3%95%E7%9A%84%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20CORR%5B%22%E8%8B%A5%E5%99%AA%E5%A3%B0%E5%BA%8F%E5%88%97%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20FAIL%5B%22%E5%99%AA%E5%A3%B0%E9%A1%B9%E4%B8%8D%E5%86%8D%E5%8F%AA%E6%98%AF%202n%CF%83%CE%B5%C2%B2%3A%20%E5%87%8F%E8%BF%87%E5%A4%B4%E6%88%96%E5%87%8F%E4%B8%8D%E5%A4%9F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">直觉类比：两尺度像用两杯不同浓度的盐水推盐量——全网格那杯「盐」多（噪声项按 \\(n\\) 涨），稀疏平均那杯「盐」少，两杯相减，纯噪声的信息就被榨出来，信号（真实波动）随之解出。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>四家都不修隔夜、都不修跳：隔夜方差按口径单列，跳由下一课处理。修正估计量对清洗极其敏感：坏 tick 表现为巨大的假噪声，带宽与子格数全部失真——先清洗，后修正。速率是渐近量：一天的 \\(n\\) 在几千到几万之间，速率差距要靠有限样本实验核实，不能拿渐近速率当实测精度。噪声方差本身随日变动（下一单元实证），今天的带宽不是明天的带宽。</p><p><span class="marginnote">常见误区：「TSRV 收敛率 \\(n^{1/4}\\) 比 \\(n^{1/2}\\) 慢，所以是落后的方法。」速率是渐近语言，实际一天的样本量下差距多大要靠有限样本实验核实；TSRV 结构简单、假设清楚，至今仍是许多日度流程的默认起点，不是「慢」就要淘汰。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共同机制：噪声的二阶结构可识别、可减除——两尺度解联立，核加权自协方差，预平均先滤波。</li><li>速率排序：TSRV 在 \\(n^{1/4}\\)，MSRV 推到任意接近 \\(n^{1/2}\\)；核与预平均以调参在同一方向竞争。</li><li>假设最弱者最耐用：相关或内生噪声下优先核与预平均，i.i.d. 减法会失准。</li><li>调参须有准则并随日更新；全年固定带宽是把渐近公式当常数用。</li><li>修正不修隔夜与跳，对清洗敏感；次序是先清洗、再修正、后检验。</li><li>出处：Zhang, Mykland and Aït-Sahalia, <em>JASA</em>, 2005；Zhang, <em>Bernoulli</em>, 2006；Aït-Sahalia, Mykland and Zhang, <em>RFS</em>, 2005；Barndorff-Nielsen, Hansen, Lunde and Shephard, <em>Econometrica</em>, 2008；Jacod, Li, Mykland, Podolskij and Vetter, 2009。</li></ul>',6))])}const D=l(h,[["render",p]]);export{g as __pageData,D as default};
